  "snippets": {
    "CorporateBand": {
      "old": "// Corporate & Group Massage announcement strip under the header (Ryan 2026-10-24; wording from the Work With Me and availability plan, 2026-10-25). Shown only on the client-facing pages listed here\n// (NOT Work With Me, NOT the corporate page itself, and not the unrelated pages on this install). Remove this snippet and the ts-corp block in Additional CSS to take it away.\n// Before November 14, 2026 (Pacific time) it says bookings begin that day; from then on it says they are open, so it does not go stale (a page held in the site cache keeps the old wording until the cache is purged).\nadd_action( 'astra_header_after', function () {\n\tif ( is_admin() || ! is_page( array( 'home', 'about', 'services', 'contact', 'privacy-policy', 'accessibility', 'thai-massage', 'therapeutic-massage', 'deep-tissue-massage', 'chair-massage' ) ) ) {\n\t\treturn;\n\t}\n\t$target = get_page_by_path( 'corporate-massage-portland' );\n\tif ( ! $target || 'publish' !== $target->post_status || is_page( $target->ID ) ) {\n\t\treturn;\n\t}\n\t$open = time() >= ( new DateTime( '2026-11-14 00:00:00', new DateTimeZone( 'America/Los_Angeles' ) ) )->getTimestamp();\n\t$head = $open ? 'Now accepting corporate &amp; group massage bookings.' : 'Currently booking corporate &amp; group massage only.';\n\t$text = $open\n\t\t? ' Thai Solitude is booking corporate and group massage at suitable Portland venues. Individual appointments at a dedicated Thai Solitude location are planned for summer 2027.'\n\t\t: ' Thai Solitude begins accepting corporate and group massage bookings on November 14, 2026, at suitable Portland venues. Individual appointments at a dedicated Thai Solitude location are planned for summer 2027.';\n\techo '<div class=\"ts-corp-band\"><div class=\"ts-corp-band__inner\">'\n\t\t. '<p class=\"ts-corp-band__label\">Corporate &amp; Group Massage &middot; Portland</p>'\n\t\t. '<p class=\"ts-corp-band__text\"><strong>' . $head . '</strong>' . $text . '</p>'\n\t\t. '<a class=\"ts-corp-band__link\" href=\"' . esc_url( get_permalink( $target ) ) . '\">Explore Corporate &amp; Group Massage <span aria-hidden=\"true\">&rarr;</span></a>'\n\t\t. '</div></div>';\n} );\n",
      "new": "// Corporate & Group Massage announcement strip under the header (Ryan 2026-10-24; wording from the Work With Me and availability plan, 2026-10-25). Shown only on the client-facing pages listed here\n// (NOT Work With Me, NOT the corporate page itself, and not the unrelated pages on this install). Remove this snippet and the ts-corp block in Additional CSS to take it away.\n// Before November 14, 2026 (Pacific time) it says bookings begin that day; from then on it says they are open, so it does not go stale (a page held in the site cache keeps the old wording until the cache is purged).\nadd_action( 'astra_header_after', function () {\n\tif ( is_admin() || ! is_page( array( 'home', 'about', 'services', 'contact', 'privacy-policy', 'accessibility', 'thai-massage', 'therapeutic-massage', 'deep-tissue-massage', 'chair-massage' ) ) ) {\n\t\treturn;\n\t}\n\t$target = get_page_by_path( 'corporate-massage-portland' );\n\tif ( ! $target || 'publish' !== $target->post_status || is_page( $target->ID ) ) {\n\t\treturn;\n\t}\n\t$open = time() >= ( new DateTime( '2026-11-14 00:00:00', new DateTimeZone( 'America/Los_Angeles' ) ) )->getTimestamp();\n\t$head = $open ? 'Now accepting corporate &amp; group massage bookings.' : 'Currently booking corporate &amp; group massage only.';\n\t$text = $open\n\t\t? ' Thai Solitude is booking corporate and group massage at suitable Portland venues. Individual appointments at a dedicated Thai Solitude location are planned for summer 2027.'\n\t\t: ' Thai Solitude begins accepting corporate and group massage bookings on November 14, 2026, at suitable Portland venues. Individual appointments at a dedicated Thai Solitude location are planned for summer 2027.';\n\t$mobile_text = $open\n\t\t? 'Now accepting corporate &amp; group massage bookings. Individual appointments are planned for summer 2027.'\n\t\t: 'Corporate &amp; group massage bookings begin November 14, 2026. Individual appointments are planned for summer 2027.';\n\techo '<div class=\"ts-corp-band\" role=\"region\" aria-label=\"Booking notice\"><div class=\"ts-corp-band__inner\">'\n\t\t. '<p class=\"ts-corp-band__label\">Corporate &amp; Group Massage &middot; Portland</p>'\n\t\t. '<p class=\"ts-corp-band__text\"><span class=\"ts-corp-band__desktop\"><strong>' . $head . '</strong>' . $text . '</span><span class=\"ts-corp-band__mobile\">' . $mobile_text . '</span></p>'\n\t\t. '<a class=\"ts-corp-band__link\" href=\"' . esc_url( get_permalink( $target ) ) . '\">Explore Corporate &amp; Group Massage <span aria-hidden=\"true\">&rarr;</span></a>'\n\t\t. '</div></div>';\n} );\n",
